import java.util.*;
import java.io.*;

public class Main {
    static final long INF = 1000 * 1000 * 1000;
    static long n = 50 * 99 + 1; // global n
    static long m;
    static long k = INF; // global k (used in flow condition)

    static class K {
        static long n, m, k, c, d;
    }

    static long[] lr = new long[51]; // 1-indexed
    static ArrayList<ArrayList<Long>> vr = new ArrayList<>(55);

    static class Rib {
        long b, u, c, f;
        int back;
    }

    // Graph: list of adjacency lists
    static ArrayList<ArrayList<Rib>> g;

    static void addRib(ArrayList<ArrayList<Rib>> g, long a, long b, long u, long c) {
        Rib r1 = new Rib();
        r1.b = b;
        r1.u = u;
        r1.c = c;
        r1.f = 0;
        r1.back = g.get((int)b).size();

        Rib r2 = new Rib();
        r2.b = a;
        r2.u = 0;
        r2.c = -c;
        r2.f = 0;
        r2.back = g.get((int)a).size();

        g.get((int)a).add(r1);
        g.get((int)b).add(r2);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        K.n = Long.parseLong(st.nextToken());
        K.m = Long.parseLong(st.nextToken());
        K.k = Long.parseLong(st.nextToken());
        K.c = Long.parseLong(st.nextToken());
        K.d = Long.parseLong(st.nextToken());

        // Initialize vr (size 55)
        for (int i = 0; i < 55; i++) vr.add(new ArrayList<>());

        // Graph with global n (4951)
        g = new ArrayList<>((int)n);
        for (int i = 0; i < (int)n; i++) g.add(new ArrayList<>());

        long tim = 99;

        // Read initial people positions (1-indexed)
        st = new StringTokenizer(br.readLine());
        for (int i = 1; i <= K.k; i++) {
            lr[i] = Long.parseLong(st.nextToken());
            addRib(g, 0, lr[i], 1, 0);
        }

        // Build edges for staying in place
        for (int j = 0; j < tim - 1; j++) {
            for (int i = 2; i <= K.n; i++) {
                addRib(g, j * 50 + i, (j + 1) * 50 + i, 50, K.c);
            }
        }

        // Build edges to sink (node 1)
        for (int j = 1; j < tim; j++) {
            addRib(g, j * 50 + 1, 1, 50, 0);
        }

        // Read edges and build moving edges
        for (int i = 0; i < K.m; i++) {
            st = new StringTokenizer(br.readLine());
            long x = Long.parseLong(st.nextToken());
            long y = Long.parseLong(st.nextToken());
            vr.get((int)x).add(y);
            vr.get((int)y).add(x);

            for (int j = 0; j < tim - 1; j++) {
                for (int l = 0; l < 50; l++) {
                    long cost = K.c + K.d * ((l + 1) * (l + 1) - l * l);
                    addRib(g, j * 50 + x, (j + 1) * 50 + y, 1, cost);
                    addRib(g, j * 50 + y, (j + 1) * 50 + x, 1, cost);
                }
            }
        }

        long s = 0, t = 1;
        long flow = 0, cost = 0;

        while (flow < k) {
            int[] id = new int[(int)n];
            long[] d = new long[(int)n];
            Arrays.fill(d, INF);
            int[] q = new int[(int)n];
            int[] p = new int[(int)n];
            int[] pRib = new int[(int)n];
            int qh = 0, qt = 0;
            q[qt++] = (int)s;
            d[(int)s] = 0;

            while (qh != qt) {
                int v = q[qh++];
                id[v] = 2;
                if (qh == (int)n) qh = 0;

                ArrayList<Rib> edges = g.get(v);
                for (int i = 0; i < edges.size(); i++) {
                    Rib r = edges.get(i);
                    if (r.f < r.u && d[v] + r.c < d[(int)r.b]) {
                        d[(int)r.b] = d[v] + r.c;
                        if (id[(int)r.b] == 0) {
                            q[qt++] = (int)r.b;
                            if (qt == (int)n) qt = 0;
                        } else if (id[(int)r.b] == 2) {
                            if (--qh < 0) qh = (int)n - 1;
                            q[qh] = (int)r.b;
                        }
                        id[(int)r.b] = 1;
                        p[(int)r.b] = v;
                        pRib[(int)r.b] = i;
                    }
                }
            }

            if (d[(int)t] == INF) break;

            long addFlow = k - flow;
            for (long v = t; v != s; v = p[(int)v]) {
                int pv = p[(int)v];
                int pr = pRib[(int)v];
                addFlow = Math.min(addFlow, g.get(pv).get(pr).u - g.get(pv).get(pr).f);
            }

            for (long v = t; v != s; v = p[(int)v]) {
                int pv = p[(int)v];
                int pr = pRib[(int)v];
                int r = g.get(pv).get(pr).back;
                g.get(pv).get(pr).f += addFlow;
                g.get((int)v).get(r).f -= addFlow;
                cost += g.get(pv).get(pr).c * addFlow;
            }
            flow += addFlow;
        }

        System.out.println(cost);
    }
}
